const bank = "BANCO DO BRASIL";
const linhas = $input.item.json.lines;

// ============================================================
// CLIENTE
// ============================================================

const clientMatch = linhas[1].match(
  /Cliente\s*([^\r\n]+)/i
);

const clientName = clientMatch
  ? clientMatch[1].trim()
  : null;


// ============================================================
// FUNÇÕES AUXILIARES
// ============================================================

function parseValor(valor) {
  return Number(
    valor
      .replace(/\./g, "")
      .replace(",", ".")
  );
}


function formatarValor(valor) {
  return valor.toLocaleString("pt-BR", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}


function dataParaTimestamp(dataTexto) {

  const [dia, mes, ano] = dataTexto.split("/");

  return new Date(
    Number(ano),
    Number(mes) - 1,
    Number(dia)
  ).getTime();
}


// ============================================================
// REGEX DA TRANSAÇÃO
// ============================================================
//
// Exemplos:
//
// 01/07/2025 50,00 (+)99020 3442510007698
// 01/07/2025 3,99 (-)13105 70101
// 10/07/2025 4.916,98 (-)99020 420344200010008 Pagto cartão crédito
//
// ============================================================

const transacaoRegex =
  /^(\d{2}\/\d{2}\/\d{4})\s+([\d.]+,\d{2})\s+\(([+-])\)(\d+)(?:\s+(\d+))?(?:\s+(.*))?$/;


// ============================================================
// LINHAS QUE DEVEM SER IGNORADAS
// ============================================================

function ignorarLinha(linha) {

  const texto = linha.toUpperCase();

  return (

    // Cabeçalhos
    texto === "EXTRATO DE CONTA CORRENTE" ||
    texto === "LANÇAMENTOS" ||
    texto === "DIA DOCUMENTO VALORLOTE HISTÓRICO" ||

    // Dados da conta
    texto.startsWith("AGÊNCIA:") ||
    texto.startsWith("PERÍODO:") ||

    // Saldos
    texto.includes("SALDO ANTERIOR") ||
    texto.includes("SALDO DO DIA") ||
    texto.includes("S A L D O") ||

    // Informações adicionais
    texto.startsWith("INFORMAÇÕES ADICIONAIS") ||
    texto.startsWith("LIMITE CLASSIC") ||
    texto.startsWith("TAXA LIMITE") ||
    texto.startsWith("TRIBUTOS") ||
    texto.startsWith("CUSTO EFETIVO") ||
    texto.startsWith("DATA VENC.") ||
    texto.startsWith("INFORMAÇÕES COMPLEMENTARES") ||
    texto.startsWith("VALOR TOTAL DEVIDO") ||
    texto.startsWith("VALOR LIBERADO") ||
    texto.startsWith("DESPESAS") ||
    texto.startsWith("TARIFA") ||
    texto.startsWith("TOTAL APLICAÇÕES") ||

    // Cliente
    texto.startsWith("CLIENTE ") ||

    // Rodapés
    texto.startsWith("(*)") ||
    texto.startsWith("BB.COM.BR") ||
    texto.startsWith("BANCO DO BRASIL") ||
    texto.startsWith("CENTRAL DE ATENDIMENTO") ||
    texto.startsWith("SAC") ||
    texto.startsWith("OUVIDORIA")
  );
}


// ============================================================
// LINHAS TÉCNICAS
// ============================================================

function ehLinhaTecnica(linha) {

  const texto = linha.toUpperCase();

  return (
    texto.startsWith("ERRO.") ||
    texto.startsWith("180957420-") ||
    texto === "RENDE FACIL" ||
    texto === "SEGURO DE VIDA" ||
    texto === "SEGURO CREDITO PROTEGIDO"
  );
}


// ============================================================
// PROCESSAMENTO
// ============================================================

const transacoes = [];

let transacaoAtual = null;


// ============================================================
// FINALIZA TRANSAÇÃO
// ============================================================

function finalizarTransacao() {

  if (!transacaoAtual) {
    return;
  }


  // ----------------------------------------------------------
  // Junta TODAS as linhas da transação
  // ----------------------------------------------------------

  const partesDescricao = transacaoAtual.descricao
    .map(item => item.trim())
    .filter(Boolean);


  // ----------------------------------------------------------
  // Remove apenas repetições consecutivas
  // ----------------------------------------------------------

  const partesLimpa = [];

  for (const parte of partesDescricao) {

    if (
      partesLimpa.length === 0 ||
      partesLimpa[partesLimpa.length - 1] !== parte
    ) {
      partesLimpa.push(parte);
    }
  }


  // ----------------------------------------------------------
  // Monta descrição
  // ----------------------------------------------------------

  const descricao = partesLimpa.length
    ? partesLimpa.join(" - ")
    : null;


  // ----------------------------------------------------------
  // Resultado
  // ----------------------------------------------------------

  const resultado = {

    data: transacaoAtual.data,

    ...(descricao
      ? { descricao }
      : {}),

    ...(transacaoAtual.documento
      ? { documento: transacaoAtual.documento }
      : {}),

    valor: formatarValor(transacaoAtual.valor),

    tipoTransacao: transacaoAtual.tipoTransacao,

    // Campo interno para ordenação
    _ordem: transacaoAtual.ordem
  };


  transacoes.push(resultado);

  transacaoAtual = null;
}


// ============================================================
// PERCORRE TODAS AS LINHAS
// ============================================================

for (let i = 0; i < linhas.length; i++) {

  const linha = linhas[i];


  // ==========================================================
  // IGNORA LINHAS IRRELEVANTES
  // ==========================================================

  if (ignorarLinha(linha)) {
    continue;
  }


  // ==========================================================
  // VERIFICA SE É UMA NOVA TRANSAÇÃO
  // ==========================================================

  const match = linha.match(transacaoRegex);


  if (match) {

    // Finaliza a transação anterior
    finalizarTransacao();


    const [
      ,
      dataTransacao,
      valorBruto,
      sinal,
      lote,
      documento,
      descricaoInicial
    ] = match;


    const valor = parseValor(valorBruto);


    // --------------------------------------------------------
    // (+) = ENTRADA
    // (-) = SAÍDA
    // --------------------------------------------------------

    const tipoTransacao =
      sinal === "+"
        ? "ENTRADA"
        : "SAIDA";


    // --------------------------------------------------------
    // Nova transação
    // --------------------------------------------------------

    transacaoAtual = {

      data: dataTransacao,

      valor,

      tipoTransacao,

      documento: documento || null,

      descricao: descricaoInicial
        ? [descricaoInicial]
        : [],

      ordem: i
    };


    continue;
  }


  // ==========================================================
  // SE NÃO ESTAMOS DENTRO DE UMA TRANSAÇÃO
  // ==========================================================

  if (!transacaoAtual) {
    continue;
  }


  // ==========================================================
  // LINHAS TÉCNICAS
  // ==========================================================

  if (ehLinhaTecnica(linha)) {
    continue;
  }


  // ==========================================================
  // ADICIONA A LINHA INTEIRA À DESCRIÇÃO
  // ==========================================================
  //
  // Não importa se é:
  //
  // 01/07 11:58
  // SHARLENE F S MAGALHAES
  // 123456
  // QUALQUER OUTRA INFORMAÇÃO
  //
  // Tudo será preservado.
  //
  // ==========================================================

  transacaoAtual.descricao.push(linha);
}


// ============================================================
// FINALIZA ÚLTIMA TRANSAÇÃO
// ============================================================

finalizarTransacao();


// ============================================================
// ORDENA POR DATA
// ============================================================

transacoes.sort((a, b) => {

  const dataA = dataParaTimestamp(a.data);
  const dataB = dataParaTimestamp(b.data);


  // Primeiro pela data
  if (dataA !== dataB) {
    return dataA - dataB;
  }


  // Depois mantém a ordem original
  return a._ordem - b._ordem;
});


// ============================================================
// REMOVE CAMPO INTERNO
// ============================================================

for (const transacao of transacoes) {
  delete transacao._ordem;
}


// ============================================================
// RESULTADO
// ============================================================

const count = transacoes.length;

return {
  bank,
  clientName,
  count,
  transacoes
};
